$stats = @{}; $currentAuthor = ""; git log --all --no-merges --pretty=tformat:"AUTHOR:%aN" --numstat -- ":(exclude)composer.lock" ":(exclude)package-lock.json" ":(exclude)build" ":(exclude)**/build" | ForEach-Object { if ($_ -like "AUTHOR:*") { $currentAuthor = $_.Substring(7); if (-not $stats.ContainsKey($currentAuthor)) { $stats[$currentAuthor] = @{ Added = 0; Deleted = 0 } } } elseif ($_ -match "^(\d+|-)\t(\d+|-)\t") { if ($matches[1] -ne "-") { $stats[$currentAuthor].Added += [int]$matches[1] }; if ($matches[2] -ne "-") { $stats[$currentAuthor].Deleted += [int]$matches[2] } } }; $stats.GetEnumerator() | ForEach-Object { [PSCustomObject]@{ Auteur = $_.Key; Ajoute = $_.Value.Added; Supprime = $_.Value.Deleted } } | Sort-Object Ajoute -Descending | Format-Table -AutoSize
